{
  "items": [
    {
      "name": "Polynomial.wronskian_add_left",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a b c : Polynomial R), (a + b).wronskian c = a.wronskian c + b.wronskian c"
    },
    {
      "name": "Polynomial.wronskian",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : CommRing R] → Polynomial R → Polynomial R → Polynomial R"
    },
    {
      "name": "Polynomial.wronskian_neg_left",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] (a b : Polynomial R), (-a).wronskian b = -a.wronskian b"
    },
    {
      "name": "HasDerivAt.finset_prod",
      "module_name": "Mathlib.Analysis.Calculus.Deriv.Mul",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u} [inst : NontriviallyNormedField 𝕜] {x : 𝕜} {ι : Type u_2} [inst_1 : DecidableEq ι] {𝔸' : Type u_3}\n  [inst_2 : NormedCommRing 𝔸'] [inst_3 : NormedAlgebra 𝕜 𝔸'] {u : Finset ι} {f : ι → 𝕜 → 𝔸'} {f' : ι → 𝔸'},\n  (∀ i ∈ u, HasDerivAt (f i) (f' i) x) → HasDerivAt (∏ i ∈ u, f i) (∑ i ∈ u, (∏ j ∈ u.erase i, f j x) • f' i) x"
    },
    {
      "name": "Polynomial.wronskianBilin",
      "module_name": "Mathlib.RingTheory.Polynomial.Wronskian",
      "kind": "definition",
      "type": "(R : Type u_1) → [inst : CommRing R] → Polynomial R →ₗ[R] Polynomial R →ₗ[R] Polynomial R"
    }
  ]
}

